cat > probe.py <<'EOF_PROBE'
# CT43 probe: download candidate BlenderKit assets, report structure, render contact grids.
import bpy, os, sys, json, uuid, math, time, urllib.request, urllib.parse
from mathutils import Vector
argv = sys.argv[sys.argv.index("--") + 1:]
OUTD = os.path.abspath(argv[0])
HOME = os.environ.get("AGENT_HOME", os.path.expanduser("~/ShortsRenderAgent"))
ADIR = os.path.join(HOME, "assets"); os.makedirs(ADIR, exist_ok=True)
UA = {"User-Agent": "blenderkit/3.21.3 (Blender 5.2.3)", "accept": "application/json"}
KEY = ""
for name, ad in bpy.context.preferences.addons.items():
    if "blenderkit" in name.lower(): KEY = getattr(ad.preferences, "api_key", "") or ""
OUT = []
def p(*a): OUT.append(" ".join(str(x) for x in a))
def fetch(url, path):
    with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": UA["User-Agent"]}), timeout=600) as r, open(path + ".part", "wb") as f:
        while True:
            b = r.read(1 << 20)
            if not b: break
            f.write(b)
    os.replace(path + ".part", path)
def bk(uid):
    pth = os.path.join(ADIR, "bk_" + uid + ".blend")
    if os.path.exists(pth) and os.path.getsize(pth) > 1000: return pth, "cached"
    errs = []
    for host in ["https://www.blenderkit.com", "https://api.blenderkit.com"]:
        try:
            h = dict(UA); h["Authorization"] = "Bearer " + KEY
            q = host + "/api/v1/downloads/" + uid + "/?" + urllib.parse.urlencode({"scene_uuid": str(uuid.uuid4())})
            r = urllib.request.urlopen(urllib.request.Request(q, headers=h), timeout=60)
            fp = json.loads(r.read().decode())["filePath"]
            fetch(fp, pth); return pth, "dl"
        except Exception as e:
            errs.append(type(e).__name__ + ":" + str(getattr(e, "code", ""))[:6])
    return None, "/".join(errs)
ITEMS = json.loads(argv[1])
for o in list(bpy.data.objects): bpy.data.objects.remove(o, do_unlink=True)
sc = bpy.context.scene
grids = {"A": [], "B": []}
for key, uid, grid in ITEMS:
    t0 = time.time()
    pth, st = bk(uid)
    p("=====", key, uid[:8], st, ("%.1fMB" % (os.path.getsize(pth) / 1e6)) if pth else "", "%.0fs" % (time.time() - t0))
    if not pth: continue
    try:
        with bpy.data.libraries.load(pth, link=False) as (df, dt):
            dt.objects = list(df.objects); dt.actions = list(df.actions)
    except Exception as e:
        p("load err", type(e).__name__, str(e)[:100]); continue
    coll = bpy.data.collections.new("C_" + key); sc.collection.children.link(coll)
    objs = [o for o in dt.objects if o is not None]
    for o in objs:
        if o.type in ("CAMERA", "LIGHT"): continue
        coll.objects.link(o)
    mn = Vector((1e9,) * 3); mx = Vector((-1e9,) * 3)
    bpy.context.view_layer.update()
    for o in coll.objects:
        if o.type == "MESH" and not o.hide_render:
            for c in o.bound_box:
                w = o.matrix_world @ Vector(c); mn = Vector(map(min, mn, w)); mx = Vector(map(max, mx, w))
    p("bbox", [round(v, 3) for v in mn], [round(v, 3) for v in mx])
    for o in coll.objects:
        info = "%s %s par=%s" % (o.type, o.name[:40], o.parent.name[:20] if o.parent else "-")
        if o.type == "MESH":
            me = o.data
            info += " v=%d mats=%s" % (len(me.vertices), [m.name[:18] for m in me.materials if m][:6])
            if me.shape_keys: info += " SK=" + ",".join(k.name for k in me.shape_keys.key_blocks)[:900]
            mods = [m.type for m in o.modifiers]
            if mods: info += " mods=" + ",".join(mods)
            if o.hide_render: info += " HIDDEN"
            info += " loc=%s dim=%s" % ([round(x, 2) for x in o.matrix_world.translation], [round(x, 2) for x in o.dimensions])
        p(" ", info)
        if o.type == "ARMATURE":
            arm = o.data
            p("   ARM", len(arm.bones), "bones; obj rot", [round(x, 2) for x in o.rotation_euler], "scale", [round(x, 3) for x in o.scale], "action", (o.animation_data.action.name if o.animation_data and o.animation_data.action else None))
            for b in arm.bones:
                d = (b.tail_local - b.head_local).normalized()
                p("   B", b.name, "<", b.parent.name if b.parent else "-", "h", [round(x, 3) for x in b.head_local], "d", [round(x, 2) for x in d], "len %.3f" % b.length, "z", [round(x, 2) for x in b.z_axis])
    acts = [a for a in dt.actions if a is not None]
    for a in acts: p("  ACTION", a.name, [round(x) for x in a.frame_range])
    imgs = set()
    for o in coll.objects:
        if o.type == "MESH":
            for m in o.data.materials:
                if m and m.use_nodes:
                    for n in m.node_tree.nodes:
                        if n.type == "TEX_IMAGE" and n.image: imgs.add(n.image.name[:40])
    p("  images", sorted(imgs)[:30])
    grids[grid].append((key, coll, mn, mx))
# layout grids and render
sc.render.engine = "BLENDER_EEVEE"
try: sc.eevee.taa_render_samples = 16
except Exception: pass
sc.render.resolution_x, sc.render.resolution_y, sc.render.resolution_percentage = 1080, 1920, 100
w = bpy.data.worlds.new("W"); sc.world = w; w.use_nodes = True
w.node_tree.nodes["Background"].inputs[0].default_value = (0.5, 0.5, 0.52, 1); w.node_tree.nodes["Background"].inputs[1].default_value = 1.0
sun = bpy.data.objects.new("sun", bpy.data.lights.new("sun", "SUN")); sun.data.energy = 3; sun.rotation_euler = (math.radians(50), 0, math.radians(-30)); sc.collection.objects.link(sun)
cd = bpy.data.cameras.new("cam"); cd.type = "ORTHO"; cam = bpy.data.objects.new("cam", cd); sc.collection.objects.link(cam); sc.camera = cam
try: sc.view_settings.view_transform = "AgX"
except Exception: pass
for g, lst in grids.items():
    if not lst: continue
    for c in bpy.data.collections:
        if c.name.startswith("C_"):
            c.hide_render = True
    for o in [o for o in sc.objects if o.name.startswith("lbl_")]: bpy.data.objects.remove(o, do_unlink=True)
    cols = 3
    for i, (key, coll, mn, mx) in enumerate(lst):
        coll.hide_render = False
        size = max(mx - mn); s = 1.0 / max(size, 1e-3)
        cx, cy = (i % cols) * 1.25, -(i // cols) * 1.55
        ctr = Vector(((mn.x + mx.x) / 2, (mn.y + mx.y) / 2, mn.z))
        for o in coll.objects:
            if o.parent is None:
                o.matrix_world = __import__("mathutils").Matrix.Translation(Vector((cx, 0, cy - 0.55))) @ __import__("mathutils").Matrix.Diagonal((s, s, s, 1)) @ __import__("mathutils").Matrix.Translation(-ctr) @ o.matrix_world
        cu = bpy.data.curves.new("lbl_" + key, "FONT"); cu.body = key; cu.size = 0.09
        lo = bpy.data.objects.new("lbl_" + key, cu); lo.location = (cx - 0.5, -0.6, cy - 0.68); lo.rotation_euler = (math.radians(90), 0, 0); sc.collection.objects.link(lo)
    rows = (len(lst) + cols - 1) // cols
    cd.ortho_scale = max(rows * 1.55, 3 * 1.25 * 16 / 9) + 0.2
    cam.location = (1.25, -10, -(rows - 1) * 1.55 / 2 - 0.1); cam.rotation_euler = (math.radians(90), 0, math.radians(0))
    # slight 3/4: rotate all? keep front
    sc.render.filepath = os.path.join(OUTD, "grid%s.png" % g)
    try: bpy.ops.render.render(write_still=True)
    except Exception as e: p("render err", e)
open(os.path.join(OUTD, "result.txt"), "w").write("\n".join(OUT) + "\n")
print("PROBE DONE")

EOF_PROBE
